1	---
2	export const prerender = true;
3	import bosses from "../data/bosses.json";
4	import { getHeroById } from "../data/heroes";
5	import Base from "../layouts/Base.astro";
6	import PageHero from "../components/PageHero.astro";
7	import "../styles/compositions.css";
8	import "../styles/events.css";
9	import { getPageUpdate } from "../utils/getPageUpdate";
10	import Analytics from '@vercel/analytics/astro';
11	const pageUpdate = getPageUpdate("bosses");
12	
13	// Player-friendly mechanic tag labels
14	const MECHANIC_LABELS = {
15	  "ENERGY_DRAIN": { label: "Energy Drain", tip: "Drains your heroes' energy over time" },
16	  "SILENCE": { label: "Silence", tip: "Prevents heroes from using skills" },
17	  "DAMAGE_REDUCTION_PHASE": { label: "Damage Reduction", tip: "Boss takes heavily reduced damage during certain phases" },
18	  "TARGETS_TOP_DPS": { label: "Targets Top DPS", tip: "Boss focuses attacks on your highest damage dealer" },
19	  "DOT_ON_TOP_DPS": { label: "DoT on DPS", tip: "Applies damage over time to your top damage dealer" },
20	  "PERCENT_HP_DAMAGE": { label: "% HP Damage", tip: "Deals damage based on max HP -- shields help" },
21	  "RAMPING_AURA": { label: "Ramps Over Time", tip: "Boss gets stronger the longer the fight lasts" },
22	  "ATK_SPEED_GLOBAL": { label: "ATK Speed Buff", tip: "Increases attack speed for all units on the field" },
23	  "CHARGE_ATTACK": { label: "Charge Attack", tip: "Boss charges through your team for burst damage" },
24	  "AOE_BURST": { label: "AoE Burst", tip: "Large area damage hitting your entire team" },
25	  "STUN": { label: "Stun", tip: "Stuns your heroes, interrupting their actions" },
26	  "BUFFS_OVER_TIME": { label: "Buffs Over Time", tip: "Boss or minions gain increasing buffs" },
27	  "KNOCKBACK": { label: "Knockback", tip: "Pushes your heroes out of position" },
28	  "FRONTAL_DAMAGE": { label: "Frontal Damage", tip: "Heavy damage in a cone to your frontline" },
29	  "BERSERK_SCALING": { label: "Berserk", tip: "Boss gains ATK and DEF as it loses HP" },
30	  "SUMMONS": { label: "Summons Minions", tip: "Boss spawns additional units to fight" },
31	  "MAIN_UNTARGETABLE": { label: "Untargetable Boss", tip: "Boss cannot be targeted directly" },
32	  "SHARED_DAMAGE": { label: "Shared Damage", tip: "Damage to minions also hurts the boss" },
33	  "ATK_SPEED_BUFF": { label: "ATK Speed Buff", tip: "Buffs minion attack speed significantly" },
34	  "RESOURCE_SCALING": { label: "Stat Scaling", tip: "Minions inherit and scale from boss stats" },
35	  "NO_DAMAGE": { label: "No Damage", tip: "Boss deals zero damage -- pure mechanic fight" },
36	  "PERMANENT_FREEZE": { label: "Permanent Freeze", tip: "Freezes heroes permanently -- cannot be removed" },
37	  "WIPE_CONDITION": { label: "Wipe Condition", tip: "All heroes frozen = instant loss" },
38	  "RANDOM_TARGET_DOT": { label: "Random Target DoT", tip: "Damages random heroes over time" },
39	  "ROOT": { label: "Root", tip: "Roots a hero in place, preventing movement" },
40	  "FIXED_TARGET_BACKLINE": { label: "Targets Backline", tip: "Always attacks the center backline hero" },
41	  "PETRIFY": { label: "Petrify", tip: "Petrifies a hero after repeated hits" },
42	  "MULTI_PART_BOSS": { label: "Multi-Part Boss", tip: "Multiple body parts with independent HP pools" },
43	  "HEAL_REDUCTION": { label: "Heal Reduction", tip: "Reduces healing received by your heroes" },
44	};
45	
46	function heroName(id) { return getHeroById(id)?.name ?? id; }
47	function heroImage(id) {
48	  const img = getHeroById(id)?.image;
49	  if (!img) return "";
50	  if (img.startsWith("http://") || img.startsWith("https://")) return img;
51	  return img.startsWith("/") ? img : `/${img}`;
52	}
53	function factionIcon(faction) {
54	  return `https://pub-a33abfbc3135413881a1d8eb86543559.r2.dev/icons/factions/${String(faction || "").toLowerCase()}.webp`;
55	}
56	function classIcon(heroClass) {
57	  return `https://pub-a33abfbc3135413881a1d8eb86543559.r2.dev/icons/classes/${String(heroClass || "").toLowerCase()}.webp`;
58	}
59	
60	const BOSS_SKILL_ICON_ALIAS = {
61	  isthar_vi: "ishtar",
62	  typhoon: "typhon"
63	};
64	function bossSkillIcon(bossId, index) {
65	  const key = BOSS_SKILL_ICON_ALIAS[bossId] || bossId;
66	  return `https://pub-a33abfbc3135413881a1d8eb86543559.r2.dev/bosses/${key}_skill_${index + 1}.png`;
67	}
68	
69	---
70	
71	<Base title="PvE Content | Motto Immortal">
72	<PageHero
73	  id="bosses"
74	  tag="PvE"
75	  headline="PvE Content"
76	  subtitle="Boss counters & recommended team comps"
77	  pageUpdate={pageUpdate}
78	/>
79	
80	<!-- Boss accordion navigation -->
81	<div class="boss-accordion-nav">
82	  <div style="width:40%; display:flex;">
83	    {bosses.bosses.map((boss, index) => (
84	      <button
85	        class={`accordion-panel ${index === 0 ? "is-active" : ""}`}
86	        type="button"
87	        data-boss-tab
88	        data-index={index}
89	      >
90	        <img
91	          src={boss.image}
92	          alt={boss.name}
93	          class="accordion-img"
94	          loading={index === 0 ? "eager" : "lazy"}
95	        />
96	        <div class="accordion-content">
97	          <span class="accordion-label-row">
98	            <span class="accordion-label">{boss.name}</span>
99	          </span>
100	        </div>
101	      </button>
102	    ))}
103	  </div>
104	</div>
105	
106	<div class="page-wrapper">
107	  <div class="content-wrapper">
108	
109	    <section class="boss-page">
110	
111	        <!-- Slides -->
112	        <div class="boss-slides" data-boss-slides>
113	          {bosses.bosses.map((boss, index) => (
114	            <article class="boss-slide" data-boss-slide data-index={index}>
115	
116	              <!-- LEFT: cinematic visual column -->
117	              <div class="boss-visual" style={`--boss-image: url(${boss.image})`}>
118	                <div class="boss-visual-scrim"></div>
119	                <div class="boss-identity">
120	                  <p class="boss-kicker" data-i18n="bosses_encounter">Boss Encounter</p>
121	                  <h2 class="boss-name">{boss.name}</h2>
122	                  <div class="boss-meta">
123	                    <span class="pill">{boss.mode}</span>
124	                    <span class="pill pill-icon">
125	                      <img class="meta-icon" src={factionIcon(boss.faction)} alt={boss.faction} />
126	                      {boss.faction}
127	                    </span>
128	                    <span class="pill pill-icon">
129	                      <img class="meta-icon" src={classIcon(boss.class)} alt={boss.class} />
130	                      {boss.class}
131	                    </span>
132	                    <span class="pill">BP {boss.battlepower}</span>
133	                  </div>
134	                  {boss.summary && <p class="boss-summary">{boss.summary}</p>}
135	                </div>
136	
137	                <!-- Prev/Next inside the visual column -->
138	                <div class="boss-nav-pair">
139	                  <button class="boss-nav boss-nav-left" aria-label="Previous boss" type="button">&#x2039;</button>
140	                  <button class="boss-nav boss-nav-right" aria-label="Next boss" type="button">&#x203A;</button>
141	                </div>
142	              </div>
143	
144	              <!-- RIGHT: info panel -->
145	              <div class="boss-panel">
146	
147	                <!-- Key Mechanics (player-friendly tags) -->
148	                {(boss.mechanicTags || []).length > 0 && (
149	                  <div class="panel-section">
150	                    <h3 class="panel-heading" data-i18n="bosses_mechanics">Key Mechanics</h3>
151	                    <div class="mechanic-tags">
152	                      {(boss.mechanicTags || []).map(tag => {
153	                        const info = MECHANIC_LABELS[tag as keyof typeof MECHANIC_LABELS];
154	                        return info ? (
155	                          <span class="mechanic-pill" title={info.tip}>{info.label}</span>
156	                        ) : null;
157	                      })}
158	                    </div>
159	                  </div>
160	                )}
161	
162	                <!-- Skills -->
163	                <div class="panel-section">
164	                  <h3 class="panel-heading" data-i18n="bosses_skills">Skills</h3>
165	                  <div class="mechanic-list">
166	                    {boss.skills.map((sk, skillIndex) => (
167	                      <div class="mechanic-item">
168	                        <img
169	                          class="skill-icon"
170	                          src={bossSkillIcon(boss.id, skillIndex)}
171	                          alt={`${boss.name} ${sk.name}`}
172	                          loading="lazy"
173	                        />
174	                        <div class="mechanic-body">
175	                          <span class="mechanic-title">
176	                            {sk.name}
177	                            <span class="mechanic-type">{sk.type}</span>
178	                          </span>
179	                          <p class="mechanic-desc">{sk.description}</p>
180	                        </div>
181	                      </div>
182	                    ))}
183	                  </div>
184	                </div>
185	
186	                <!-- Strategy Notes -->
187	                {boss.strategyNotes && (
188	                  <div class="panel-section">
189	                    <h3 class="panel-heading" data-i18n="bosses_strategy">Strategy Notes</h3>
190	                    <p class="strategy-text">{boss.strategyNotes}</p>
191	                  </div>
192	                )}
193	
194	                <!-- Recommended Comps -->
195	                {(boss.recommendedComps || []).length > 0 && (
196	                  <div class="panel-section">
197	                    <h3 class="panel-heading" data-i18n="bosses_comps">Recommended Comps</h3>
198	                    <div class="comp-list">
199	                      {(boss.recommendedComps || []).map(comp => {
200	                        const heroComp = String(comp["hero-comp"] || "")
201	                          .split(",")
202	                          .map(e => e.trim())
203	                          .filter(Boolean);
204	                        const resolvedHeroes = heroComp.length ? heroComp : (comp.heroes ?? []);
205	                        return (
206	                          <div class="comp-entry">
207	                            <div class="comp-entry-header">
208	                              <span class="comp-label">{comp.label}</span>
209	                              {comp.reason && <p class="comp-reason">{comp.reason}</p>}
210	                            </div>
211	                            <div class="comp-hero-row">
212	                              {resolvedHeroes.map(id => (
213	                                <a href={`/heroes/${id}`} class="hero-chip">
214	                                  <img src={heroImage(id)} alt={heroName(id)} />
215	                                  <span class="hero-chip-name">{heroName(id)}</span>
216	                                </a>
217	                              ))}
218	                            </div>
219	                            {comp.notes?.length > 0 && (
220	                              <ul class="comp-notes">
221	                                {comp.notes.map(n => <li>{n}</li>)}
222	                              </ul>
223	                            )}
224	                          </div>
225	                        );
226	                      })}
227	                    </div>
228	                  </div>
229	                )}
230	
231	              </div>
232	            </article>
233	          ))}
234	        </div>
235	      </section>
236	
237	  </div>
238	</div>
239	
240	</Base>
241	
242	<style is:global>
243	  /* Page wrapper for content below PageHero */
244	  .page-wrapper {
245	    max-width: 1400px;
246	    margin: 0 auto;
247	    padding: 0px 16px 0;
248	  }
249	</style>
250	
251	<style>
252	  /* ── BOSS ACCORDION NAVIGATION ── */
253	  .boss-accordion-nav {
254	    display: flex;
255	    height: 200px;
256	    overflow: hidden;
257	    background: #0d0a0a;
258	    width: 100%;
259	    justify-content: center;
260	  }
261	
262	  .accordion-panel {
263	    position: relative;
264	    flex: 0 0 95px;
265	    border: none;
266	    padding: 0;
267	    cursor: pointer;
268	    overflow: hidden;
269	    font-family: inherit;
270	    transition: flex 420ms cubic-bezier(0.4, 0, 0.2, 1);
271	    outline: none;
272	    border-radius: 0;
273	    background: transparent;
274	    border-left: 1px solid rgba(255,255,255,0.06);
275	  }
276	
277	  .accordion-panel:first-child {
278	    border-left: none;
279	  }
280	
281	  .accordion-panel.is-active {
282	    flex: 1 1 0;
283	    cursor: default;
284	  }
285	
286	  /* Boss image layer */
287	  .accordion-img {
288	    position: absolute;
289	    inset: 0;
290	    width: 100%;
291	    height: 100%;
292	    object-fit: cover;
293	    object-position: center 20%;
294	    transform: scale(1.05);
295	    filter: brightness(0.3) saturate(0.4);
296	    transition: transform 420ms cubic-bezier(0.4, 0, 0.2, 1),
297	                filter 420ms cubic-bezier(0.4, 0, 0.2, 1);
298	    pointer-events: none;
299	  }
300	
301	  .accordion-panel.is-active .accordion-img {
302	    transform: scale(1);
303	    filter: brightness(0.85) saturate(1.1);
304	  }
305	
306	  .accordion-panel:not(.is-active):hover .accordion-img {
307	    filter: brightness(0.45) saturate(0.6);
308	  }
309	
310	  /* Gradient overlay for text readability */
311	  .accordion-panel::before {
312	    content: "";
313	    position: absolute;
314	    inset: 0;
315	    z-index: 1;
316	    background: linear-gradient(
317	      to top,
318	      rgba(0, 0, 0, 0.85) 0%,
319	      rgba(0, 0, 0, 0.15) 30%,
320	      transparent 50%
321	    );
322	    transition: background 420ms ease;
323	  }
324	
325	  .accordion-panel.is-active::before {
326	    background:
327	      linear-gradient(
328	        to top,
329	        rgba(0, 0, 0, 0.6) 0%,
330	        rgba(0, 0, 0, 0.1) 25%,
331	        transparent 45%
332	      );
333	  }
334	
335	  /* Accent border for active panel */
336	  .accordion-panel.is-active::after {
337	    content: "";
338	    position: absolute;
339	    bottom: 0;
340	    left: 0;
341	    right: 0;
342	    height: 3px;
343	    background: linear-gradient(90deg, #facc15, #5eead4);
344	    z-index: 3;
345	  }
346	
347	  /* Content layout */
348	  .accordion-content {
349	    position: relative;
350	    z-index: 2;
351	    display: flex;
352	    flex-direction: column;
353	    justify-content: flex-end;
354	    align-items: flex-start;
355	    height: 100%;
356	    padding: 14px;
357	    color: #fff;
358	    text-align: left;
359	  }
360	
361	  /* Boss name label */
362	  .accordion-label {
363	    font-size: 0.78rem;
364	    font-weight: 700;
365	    letter-spacing: 0.04em;
366	    text-shadow: 0 2px 10px rgba(0,0,0,0.9), 0 1px 3px rgba(0,0,0,0.8);
367	    white-space: normal;
368	    word-break: break-word;
369	    transition: font-size 320ms ease;
370	
371	  }
372	
373	  .accordion-label-row {
374	    display: inline-flex;
375	    align-items: center;
376	    gap: 8px;
377	    min-width: 0;
378	  }
379	
380	  .accordion-panel.is-active .accordion-label {
381	    font-size: 1.4rem;
382	  }
383	
384	  @media (max-width: 768px) {
385	    .boss-accordion-nav {
386	      height: 160px;
387	    }
388	    .accordion-panel {
389	      flex: 0 0 52px;
390	    }
391	    .accordion-panel.is-active .accordion-label {
392	      font-size: 1.1rem;
393	    }
394	    .accordion-content {
395	      padding: 10px;
396	    }
397	  }
398	
399	  @media (max-width: 400px) {
400	    .boss-accordion-nav {
401	      height: 120px;
402	    }
403	    .accordion-panel {
404	      flex: 0 0 40px;
405	    }
406	    .accordion-panel.is-active .accordion-label {
407	      font-size: 0.95rem;
408	    }
409	  }
410	</style>
411	
412	<!-- Boss tab switching script -->
413	<script>
414	  const slides = Array.from(document.querySelectorAll("[data-boss-slide]"));
415	  const bossTabs = Array.from(document.querySelectorAll("[data-boss-tab]"));
416	  const prevBtns = Array.from(document.querySelectorAll(".boss-nav-left"));
417	  const nextBtns = Array.from(document.querySelectorAll(".boss-nav-right"));
418	  let currentIndex = 0;
419	
420	  function updateSlides(index) {
421	    currentIndex = (index + slides.length) % slides.length;
422	    slides.forEach((s, i) => s.classList.toggle("is-active", i === currentIndex));
423	    bossTabs.forEach((t, i) => t.classList.toggle("is-active", i === currentIndex));
424	  }
425	
426	  if (slides.length) updateSlides(0);
427	
428	  prevBtns.forEach(b => b.addEventListener("click", () => updateSlides(currentIndex - 1)));
429	  nextBtns.forEach(b => b.addEventListener("click", () => updateSlides(currentIndex + 1)));
430	  bossTabs.forEach(tab => {
431	    tab.addEventListener("click", () => updateSlides(Number(tab.dataset.index || 0)));
432	  });
433	  document.addEventListener("keydown", e => {
434	    if (e.key === "ArrowLeft") updateSlides(currentIndex - 1);
435	    if (e.key === "ArrowRight") updateSlides(currentIndex + 1);
436	  });
437	</script>
438	
