608	  padding: 0 6px;
609	  font-size: 0.7rem;
610	  font-weight: 600;
611	  border-radius: 4px;
612	  background: rgba(255, 255, 255, 0.07);
613	  color: rgba(230, 230, 235, 0.65);
614	  white-space: nowrap;
615	}
