---
export const prerender = true;
import HeroCard from "../components/HeroCard.astro";
import { heroes } from "../data/heroes";
import Base from "../layouts/Base.astro";
import PageHero from "../components/PageHero.astro";
import Filter from "../components/filter.astro";


/* Alphabetisch nach Name sortieren */

// Only show released heroes
const sortedHeroes = [...heroes]
  .filter(hero => hero.release !== false)
  .sort((a, b) => a.name.localeCompare(b.name, "en", { sensitivity: "base" }));


/* No need for escapeRegExp anymore */



---

<Base
  title="Heroes | Motto Immortal Database"
  description="Browse all heroes in Motto Immortal. Filter by class, faction, role and ratings. View stats, skills and tier rankings for every hero."
>
<PageHero
  id="heros"
  tag="Hero Database"
  headline="Choose your hero"
  subtitle="Browse all heroes, stats, skills & synergies"
/>

 <div class="page-wrapper"> 
<Filter />

<!-- RESULTS -->

<div class="resultcontent">
  <div class="sort-bar">
    <p id="heroCounter" class="hero-counter" data-i18n-counter>0 Heroes shown</p>
    <div class="sort-controls">
      <label for="sortSelect" class="sort-label" data-i18n="heros_sort_by">Sort by</label>
      <select id="sortSelect" class="sort-select">
        <option value="name-asc" data-i18n="heros_sort_name_asc">Name (A-Z)</option>
        <option value="name-desc" data-i18n="heros_sort_name_desc">Name (Z-A)</option>
        <option value="rating-desc" data-i18n="heros_sort_rating_desc">Rating (best first)</option>
        <option value="rating-asc" data-i18n="heros_sort_rating_asc">Rating (worst first)</option>
        <option value="class" data-i18n="heros_sort_class">Class</option>
        <option value="rarity-desc" data-i18n="heros_sort_rarity_desc">Rarity (highest first)</option>
      </select>
      <div class="view-toggle" role="group" aria-label="View mode">
        <button id="viewGrid" class="view-btn active" title="Gallery view" aria-label="Gallery view">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
