<script>
document.addEventListener("DOMContentLoaded", () => {
  const searchInput = document.getElementById("searchInput") as HTMLInputElement;
  const resetButton = document.getElementById("resetFilters");
  const heroCounter = document.getElementById("heroCounter");
  const heroGrid = document.getElementById("heroGrid") as HTMLElement;
  const heroList = document.getElementById("heroList") as HTMLElement;
  const heroListBody = document.getElementById("heroListBody") as HTMLElement;
  const sortSelect = document.getElementById("sortSelect") as HTMLSelectElement;
  const viewGridBtn = document.getElementById("viewGrid") as HTMLButtonElement;
  const viewListBtn = document.getElementById("viewList") as HTMLButtonElement;

  const roleChips = document.querySelectorAll(".role-chip");
  const factionChips = document.querySelectorAll(".faction-chip");
  const heroCards = document.querySelectorAll<HTMLElement>(".hero-wrapper");
  const listRows = document.querySelectorAll<HTMLElement>(".hero-row");
  const classChips = document.querySelectorAll(".class-chip");
  const rarityChips = document.querySelectorAll(".rarity-chip");
  const tagChips = document.querySelectorAll(".tag-chip");

  const RATING_ORDER: Record<string, number> = { sss: 7, ss: 6, s: 5, a: 4, b: 3, c: 2, d: 1, "n/a": 0 };
  const RARITY_ORDER: Record<string, number> = { legendary: 3, epic: 2, common: 1 };

  let activeTag: string | null = null;
  let activeRoles = new Set<string>();
  let activeClasses = new Set<string>();
  let activeRarities = new Set<string>();
  let activeFactions = new Set<string>();

  // ---- View toggle ----

  let currentView: "grid" | "list" = (localStorage.getItem("heroView") as "grid" | "list") || "grid";

  function setView(v: "grid" | "list") {
    currentView = v;
    localStorage.setItem("heroView", v);
    if (v === "grid") {
      heroGrid.style.display = "";
      heroList.style.display = "none";
      viewGridBtn.classList.add("active");
      viewListBtn.classList.remove("active");
    } else {
      heroGrid.style.display = "none";
      heroList.style.display = "";
      viewGridBtn.classList.remove("active");
      viewListBtn.classList.add("active");
    }
  }

  viewGridBtn.addEventListener("click", () => setView("grid"));
  viewListBtn.addEventListener("click", () => setView("list"));

  // apply persisted view on load
  setView(currentView);

  // ---- Filtering ----

  function matchesFilters(el: HTMLElement): boolean {
    const query = (searchInput.value || "").toLowerCase();
    const name = el.dataset.name || "";
    const cls = el.dataset.class || "";
    const role = el.dataset.role || "";
    const rarity = el.dataset.rarity || "";
    const faction = el.dataset.faction || "";
    const tags = el.dataset.tags || "";

    return (
      (!activeTag || tags.includes(activeTag)) &&
      (!query || name.includes(query) || cls.includes(query) || role.includes(query) || faction.includes(query) || rarity.includes(query)) &&
      (activeClasses.size === 0 || activeClasses.has(cls)) &&
      (activeRoles.size === 0 || activeRoles.has(role)) &&
      (activeRarities.size === 0 || activeRarities.has(rarity)) &&
      (activeFactions.size === 0 || activeFactions.has(faction))
    );
  }

  function applyFilters() {
    let visible = 0;
    heroCards.forEach(card => {
      const show = matchesFilters(card);
      card.style.display = show ? "block" : "none";
      if (show) visible++;
    });
    listRows.forEach(row => {
      row.style.display = matchesFilters(row) ? "" : "none";
    });
    const lang = localStorage.getItem('lang') || 'en';
    const suffix = lang === 'ru' ? ' Героев показано' : ' Heroes shown';
    heroCounter!.textContent = `${visible}${suffix}`;
  }

  // ---- Sorting ----

  const TIER_ORDER: Record<string, number> = { "T0": 1, "T0.5": 2, "T1": 3, "T2": 4, "T10": 5, "": 9 };

  const ratingVal  = (el: HTMLElement) => RATING_ORDER[el.dataset.rating || ""] ?? 0;
  const rarityVal  = (el: HTMLElement) => RARITY_ORDER[el.dataset.rarity || ""] ?? 0;
  const nameVal    = (el: HTMLElement) => el.dataset.name || "";

  function dropdownCompareFn(a: HTMLElement, b: HTMLElement): number {
    const value = sortSelect.value;
    switch (value) {
      case "name-asc":    return nameVal(a).localeCompare(nameVal(b));
      case "name-desc":   return nameVal(b).localeCompare(nameVal(a));
      case "rating-desc": { const d = ratingVal(b) - ratingVal(a); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
      case "rating-asc":  { const d = ratingVal(a) - ratingVal(b); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
      case "class":       return (a.dataset.class || "").localeCompare(b.dataset.class || "");
      case "rarity-desc": { const d = rarityVal(b) - rarityVal(a); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
      default: return 0;
    }
  }

  function sortHeroes() {
    // sort grid cards by dropdown
    Array.from(heroGrid.querySelectorAll<HTMLElement>(".hero-wrapper"))
      .sort(dropdownCompareFn)
      .forEach(el => heroGrid.appendChild(el));
    // sort list rows by dropdown (resets column sort)
    Array.from(heroListBody.querySelectorAll<HTMLElement>(".hero-row"))
      .sort(dropdownCompareFn)
      .forEach(el => heroListBody.appendChild(el));
    // clear column sort state
    listSortCol = null;
    listSortDir = "asc";
    updateColHeaders();
  }

  sortSelect.addEventListener("change", () => { sortHeroes(); applyFilters(); });

  // ---- Column header sorting (list view only) ----

  let listSortCol: string | null = null;
  let listSortDir: "asc" | "desc" = "asc";

  function updateColHeaders() {
    document.querySelectorAll<HTMLElement>(".col-sortable").forEach(th => {
      th.classList.remove("sort-asc", "sort-desc");
      if (th.dataset.col === listSortCol) {
        th.classList.add(listSortDir === "asc" ? "sort-asc" : "sort-desc");
      }
    });
  }

  function sortListByCol(col: string) {
    if (listSortCol === col) {
      listSortDir = listSortDir === "asc" ? "desc" : "asc";
    } else {
      listSortCol = col;
      listSortDir = col === "overall" || col === "pvp" || col === "pve" ? "desc" : "asc";
    }

    const dir = listSortDir === "asc" ? 1 : -1;

    Array.from(heroListBody.querySelectorAll<HTMLElement>(".hero-row"))
      .sort((a, b) => {
        switch (col) {
          case "name":
            return dir * nameVal(a).localeCompare(nameVal(b));
          case "overall": {
            const d = (RATING_ORDER[a.dataset.rating || ""] ?? 0) - (RATING_ORDER[b.dataset.rating || ""] ?? 0);
            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
          }
          case "pvp": {
            const d = (RATING_ORDER[a.dataset.pvp || ""] ?? 0) - (RATING_ORDER[b.dataset.pvp || ""] ?? 0);
            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
          }
          case "pve": {
            const d = (RATING_ORDER[a.dataset.pve || ""] ?? 0) - (RATING_ORDER[b.dataset.pve || ""] ?? 0);
            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
          }
          case "tier": {
            const ta = TIER_ORDER[a.dataset.excelTier || ""] ?? 9;
            const tb = TIER_ORDER[b.dataset.excelTier || ""] ?? 9;
            const d = ta - tb;
            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
          }
          default: return 0;
        }
      })
      .forEach(el => heroListBody.appendChild(el));

    updateColHeaders();
    applyFilters();
  }

  document.querySelectorAll<HTMLElement>(".col-sortable").forEach(th => {
    th.addEventListener("click", () => sortListByCol(th.dataset.col || ""));
  });

  // ---- Chip filters ----

  searchInput.addEventListener("input", applyFilters);

  roleChips.forEach(chip => {
    chip.addEventListener("click", () => {
      const r = (chip as HTMLElement).dataset.role || "";
      activeRoles.has(r) ? activeRoles.delete(r) : activeRoles.add(r);
      chip.classList.toggle("active");
      applyFilters();
    });
  });

  classChips.forEach(chip => {
    chip.addEventListener("click", () => {
      const c = (chip as HTMLElement).dataset.class || "";
      chip.classList.toggle("active");
      activeClasses.has(c) ? activeClasses.delete(c) : activeClasses.add(c);
      applyFilters();
    });
  });

  factionChips.forEach(chip => {
    chip.addEventListener("click", () => {
      const c = (chip as HTMLElement).dataset.faction || "";
      chip.classList.toggle("active");
      activeFactions.has(c) ? activeFactions.delete(c) : activeFactions.add(c);
      applyFilters();
    });
  });

  rarityChips.forEach(chip => {
    chip.addEventListener("click", () => {
      const r = (chip as HTMLElement).dataset.rarity || "";
      chip.classList.toggle("active");
      activeRarities.has(r) ? activeRarities.delete(r) : activeRarities.add(r);
      applyFilters();
    });
  });

  tagChips.forEach(chip => {
    chip.addEventListener("click", () => {
      const t = ((chip as HTMLElement).dataset.tag || "").toLowerCase();
      if (activeTag === t) {
        activeTag = null;
        chip.classList.remove("active");
      } else {
        activeTag = t;
        tagChips.forEach(x => x.classList.remove("active"));
        chip.classList.add("active");
      }
      applyFilters();
    });
  });

  resetButton!.addEventListener("click", () => {
    searchInput.value = "";
    activeClasses.clear();
    activeRarities.clear();
    activeRoles.clear();
    activeFactions.clear();
    activeTag = null;
    document.querySelectorAll(".chip.active, .role-chip.active").forEach(c => c.classList.remove("active"));
    tagChips.forEach(x => x.classList.remove("active"));
    sortSelect.value = "name-asc";
    sortHeroes();
    applyFilters();
  });

  applyFilters();
});
</script>

