725	                )}
726	              </div>
727	            );
728	          })}
729	        </div>
730	      </section>
731	    )}
732	
733	    <!-- ── SECTION 9: VIDEO GUIDES ── -->
734	    {(hero as any)["content-creator"] && (hero as any)["content-creator"].length > 0 && (
735	      <section class="content-section" id="section-videos">
736	        <div class="section-label" data-i18n="detail_videos">Video Guides</div>
737	        <div class="video-grid">
738	          {(hero as any)["content-creator"].map((guide: { titel: string; autor: string; videoId: string }) => (
739	            <div class="video-card">
740	              <div class="video-wrapper">
741	                <iframe
742	                  src={`https://www.youtube.com/embed/${guide.videoId}`}
743	                  title={guide.titel}
744	                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
745	                  style="border:none;"
746	                  referrerpolicy="strict-origin-when-cross-origin"
747	                  allowfullscreen
748	                  loading="lazy"
749	                ></iframe>
750	              </div>
