1	/* ============================================================
2	   DESIGN TOKENS
3	   Single source of truth for all visual decisions.
4	   Import this file first in any page or component.
5	   ============================================================ */
6	
7	:root {
8	
9	  /* ============================================================
10	     CORE PALETTE
11	     ============================================================ */
12	
13	  /* Backgrounds (darkest to lightest surface) */
14	  --bg-base:       #07060c;   /* page background */
15	  --bg-surface:    #0d0b14;   /* cards, panels */
16	  --bg-raised:     #13111c;   /* elevated elements, dropdowns */
17	  --bg-overlay:    #1a1726;   /* modals, sheets */
18	
19	  /* Backwards-compatible aliases */
20	  --bg-primary:    var(--bg-base);
21	  --bg-secondary:  var(--bg-surface);
22	
23	  /* Text */
24	  --text-bright:   #f4f1ff;
25	  --text-primary:  #e6e6eb;
26	  --text-secondary: rgba(230, 230, 235, 0.70);
27	  --text-muted:    rgba(230, 230, 235, 0.45);
28	  --text-disabled: rgba(230, 230, 235, 0.25);
29	
