31	  --accent-gold:   #facc15;
32	  --accent-gold-dim: rgba(250, 204, 21, 0.15);
33	  --accent-purple: #a855f7;
34	  --accent-purple-dim: rgba(168, 85, 247, 0.15);
35	  --gold:          #d4af37;
36	  --accent-new:    #15b109;
37	
