59	
60	  --tier-s-from:   #fde68a;
61	  --tier-s-to:     #fbbf24;
62	  --tier-s-text:   #3a2a00;
63	  --tier-s-glow:   rgba(251, 191, 36, 0.35);
64	
65	  --tier-a-from:   #fdba74;
66	  --tier-a-to:     #fb923c;
67	  --tier-a-text:   #3b1d00;
68	
69	  --tier-b-from:   #c4b5fd;
70	  --tier-b-to:     #8b5cf6;
71	  --tier-b-text:   #1e103a;
72	
73	  --tier-c-from:   #93c5fd;
74	  --tier-c-to:     #3b82f6;
75	  --tier-c-text:   #001a33;
76	
77	  --tier-d-from:   #5eead4;
78	  --tier-d-to:     #14b8a6;
79	  --tier-d-text:   #002c26;
80	
81	
82	  /* ============================================================
83	     SPACING SCALE (8pt base)
84	     ============================================================ */
85	
86	  --space-1:  4px;
87	  --space-2:  8px;
88	  --space-3:  12px;
89	  --space-4:  16px;
90	  --space-5:  20px;
91	  --space-6:  24px;
92	  --space-8:  32px;
93	  --space-10: 40px;
94	  --space-12: 48px;
95	  --space-16: 64px;
96	  --space-20: 80px;
97	  --space-24: 96px;
98	
99	  /* Backwards-compatible aliases */
100	  --space-xs:  var(--space-1);
101	  --space-sm:  var(--space-2);
102	  --space-md:  var(--space-4);
103	  --space-lg:  var(--space-6);
104	  --space-xl:  var(--space-8);
105	  --space-2xl: var(--space-12);
106	  --space-3xl: var(--space-16);
107	
108	
109	  /* ============================================================
110	     TYPOGRAPHY SCALE
111	     ============================================================ */
112	
113	  /* Font families */
114	  --font-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
115	  --font-mono: "SF Mono", "Fira Code", "Cascadia Code", monospace;
116	
117	  /* Size scale */
118	  --text-xs:   11px;
119	  --text-sm:   13px;
120	  --text-base: 15px;
121	  --text-md:   16px;
122	  --text-lg:   18px;
123	  --text-xl:   20px;
124	  --text-2xl:  24px;
125	  --text-3xl:  30px;
126	  --text-4xl:  38px;
127	
128	  /* Weight */
129	  --weight-normal:    400;
130	  --weight-medium:    500;
131	  --weight-semibold:  600;
132	  --weight-bold:      700;
133	
134	  /* Line height */
135	  --leading-tight:  1.2;
136	  --leading-snug:   1.35;
137	  --leading-normal: 1.5;
138	  --leading-loose:  1.7;
139	
140	  /* Letter spacing */
