149	     ============================================================ */
150	
151	  --radius-sm:   4px;
152	  --radius-md:   8px;
153	  --radius-lg:   12px;
154	  --radius-xl:   16px;
155	  --radius-2xl:  20px;
156	  --radius-full: 9999px;
157	
158	
159	  /* ============================================================
160	     ELEVATION (prefer bg tints over shadows for clean look)
161	     Use shadows sparingly — only for floating elements.
162	     ============================================================ */
163	
164	  /* Subtle tint for "elevated" surfaces — no shadow needed */
165	  --surface-tint: rgba(255, 255, 255, 0.03);
166	
167	  /* Shadows: use only for dropdowns, modals, tooltips */
168	  --shadow-sm:  0 1px 3px rgba(0, 0, 0, 0.4);
169	  --shadow-md:  0 4px 12px rgba(0, 0, 0, 0.5);
170	  --shadow-lg:  0 8px 32px rgba(0, 0, 0, 0.6);
171	  --shadow-xl:  0 16px 48px rgba(0, 0, 0, 0.7);
172	
173	
174	  /* ============================================================
175	     Z-INDEX SCALE
176	     ============================================================ */
177	
178	  --z-base:     0;
179	  --z-raised:   10;
180	  --z-dropdown: 100;
181	  --z-overlay:  200;
182	  --z-modal:    300;
183	  --z-toast:    400;
184	  --z-nav:      500;
185	
186	
187	  /* ============================================================
188	     TRANSITIONS
189	     ============================================================ */
190	
191	  --ease-out:   cubic-bezier(0.0, 0.0, 0.2, 1);
192	  --ease-in:    cubic-bezier(0.4, 0.0, 1, 1);
193	  --ease-inout: cubic-bezier(0.4, 0.0, 0.2, 1);
194	
195	  --duration-fast:   120ms;
196	  --duration-normal: 200ms;
197	  --duration-slow:   350ms;
198	
199	  --transition-colors: color var(--duration-normal) var(--ease-out),
200	                       background-color var(--duration-normal) var(--ease-out),
201	                       border-color var(--duration-normal) var(--ease-out);
202	
203	  --transition-transform: transform var(--duration-normal) var(--ease-out);
204	  --transition-opacity:   opacity var(--duration-normal) var(--ease-out);
205	  --transition-all:       all var(--duration-normal) var(--ease-out);
206	
207	
208	  /* ============================================================
209	     COMPONENT TOKENS
210	     These map semantic intent to palette values.
211	     Change here to update all components at once.
212	     ============================================================ */
213	
214	  /* --- Chip / Filter Tag --- */
215	  --chip-bg:           rgba(255, 255, 255, 0.06);
216	  --chip-bg-hover:     rgba(255, 255, 255, 0.10);
