/* ============================================================
   DESIGN TOKENS
   Single source of truth for all visual decisions.
   Import this file first in any page or component.
   ============================================================ */

:root {

  /* ============================================================
     CORE PALETTE
     ============================================================ */

  /* Backgrounds (darkest to lightest surface) */
  --bg-base:       #07060c;   /* page background */
  --bg-surface:    #0d0b14;   /* cards, panels */
  --bg-raised:     #13111c;   /* elevated elements, dropdowns */
  --bg-overlay:    #1a1726;   /* modals, sheets */

  /* Backwards-compatible aliases */
  --bg-primary:    var(--bg-base);
  --bg-secondary:  var(--bg-surface);

  /* Text */
  --text-bright:   #f4f1ff;
  --text-primary:  #e6e6eb;
  --text-secondary: rgba(230, 230, 235, 0.70);
  --text-muted:    rgba(230, 230, 235, 0.45);
  --text-disabled: rgba(230, 230, 235, 0.25);

  /* Accents */
  --accent-gold:   #facc15;
  --accent-gold-dim: rgba(250, 204, 21, 0.15);
  --accent-purple: #a855f7;
  --accent-purple-dim: rgba(168, 85, 247, 0.15);
  --gold:          #d4af37;
  --accent-new:    #15b109;

  /* Borders (prefer these over box-shadow for separation) */
  --border-faint:  rgba(255, 255, 255, 0.05);
  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-medium: rgba(255, 255, 255, 0.15);
  --border-strong: rgba(255, 255, 255, 0.28);


  /* ============================================================
     RATING TIER COLORS
     Canonical source — used by HeroCard and rating badges.
     ============================================================ */

  --tier-sss-from: #ff4d4d;
  --tier-sss-to:   #b91c1c;
  --tier-sss-text: #fff5f5;
  --tier-sss-glow: rgba(255, 60, 60, 0.55);

  --tier-ss-from:  #ffe066;
  --tier-ss-to:    #facc15;
  --tier-ss-text:  #3a2a00;
  --tier-ss-glow:  rgba(255, 224, 102, 0.35);

  --tier-s-from:   #fde68a;
  --tier-s-to:     #fbbf24;
  --tier-s-text:   #3a2a00;
  --tier-s-glow:   rgba(251, 191, 36, 0.35);

  --tier-a-from:   #fdba74;
  --tier-a-to:     #fb923c;
  --tier-a-text:   #3b1d00;

  --tier-b-from:   #c4b5fd;
  --tier-b-to:     #8b5cf6;
  --tier-b-text:   #1e103a;

  --tier-c-from:   #93c5fd;
  --tier-c-to:     #3b82f6;
  --tier-c-text:   #001a33;

  --tier-d-from:   #5eead4;
  --tier-d-to:     #14b8a6;
  --tier-d-text:   #002c26;


  /* ============================================================
     SPACING SCALE (8pt base)
     ============================================================ */

  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* Backwards-compatible aliases */
  --space-xs:  var(--space-1);
  --space-sm:  var(--space-2);
  --space-md:  var(--space-4);
  --space-lg:  var(--space-6);
  --space-xl:  var(--space-8);
  --space-2xl: var(--space-12);
  --space-3xl: var(--space-16);


  /* ============================================================
     TYPOGRAPHY SCALE
     ============================================================ */

  /* Font families */
  --font-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "SF Mono", "Fira Code", "Cascadia Code", monospace;

  /* Size scale */
  --text-xs:   11px;
  --text-sm:   13px;
  --text-base: 15px;
  --text-md:   16px;
  --text-lg:   18px;
  --text-xl:   20px;
  --text-2xl:  24px;
  --text-3xl:  30px;
  --text-4xl:  38px;

  /* Weight */
  --weight-normal:    400;
  --weight-medium:    500;
  --weight-semibold:  600;
  --weight-bold:      700;

  /* Line height */
  --leading-tight:  1.2;
  --leading-snug:   1.35;
  --leading-normal: 1.5;
  --leading-loose:  1.7;

  /* Letter spacing */
  --tracking-tight:  -0.02em;
  --tracking-normal:  0em;
  --tracking-wide:    0.04em;
  --tracking-widest:  0.10em;


  /* ============================================================
     BORDER RADIUS SCALE
     ============================================================ */

  --radius-sm:   4px;
  --radius-md:   8px;
  --radius-lg:   12px;
  --radius-xl:   16px;
  --radius-2xl:  20px;
  --radius-full: 9999px;


  /* ============================================================
     ELEVATION (prefer bg tints over shadows for clean look)
     Use shadows sparingly — only for floating elements.
     ============================================================ */

  /* Subtle tint for "elevated" surfaces — no shadow needed */
  --surface-tint: rgba(255, 255, 255, 0.03);

  /* Shadows: use only for dropdowns, modals, tooltips */
  --shadow-sm:  0 1px 3px rgba(0, 0, 0, 0.4);
  --shadow-md:  0 4px 12px rgba(0, 0, 0, 0.5);
  --shadow-lg:  0 8px 32px rgba(0, 0, 0, 0.6);
  --shadow-xl:  0 16px 48px rgba(0, 0, 0, 0.7);


  /* ============================================================
     Z-INDEX SCALE
     ============================================================ */

  --z-base:     0;
  --z-raised:   10;
  --z-dropdown: 100;
  --z-overlay:  200;
  --z-modal:    300;
  --z-toast:    400;
  --z-nav:      500;


  /* ============================================================
     TRANSITIONS
     ============================================================ */

  --ease-out:   cubic-bezier(0.0, 0.0, 0.2, 1);
  --ease-in:    cubic-bezier(0.4, 0.0, 1, 1);
  --ease-inout: cubic-bezier(0.4, 0.0, 0.2, 1);

  --duration-fast:   120ms;
  --duration-normal: 200ms;
  --duration-slow:   350ms;

  --transition-colors: color var(--duration-normal) var(--ease-out),
                       background-color var(--duration-normal) var(--ease-out),
                       border-color var(--duration-normal) var(--ease-out);

  --transition-transform: transform var(--duration-normal) var(--ease-out);
  --transition-opacity:   opacity var(--duration-normal) var(--ease-out);
  --transition-all:       all var(--duration-normal) var(--ease-out);


  /* ============================================================
     COMPONENT TOKENS
     These map semantic intent to palette values.
     Change here to update all components at once.
     ============================================================ */

  /* --- Chip / Filter Tag --- */
  --chip-bg:           rgba(255, 255, 255, 0.06);
  --chip-bg-hover:     rgba(255, 255, 255, 0.10);
  --chip-bg-active:    var(--accent-purple-dim);
  --chip-border:       var(--border-subtle);
  --chip-border-active: var(--accent-purple);
  --chip-text:         var(--text-secondary);
  --chip-text-active:  var(--accent-purple);
  --chip-radius:       var(--radius-full);
  --chip-height:       32px;
  --chip-padding:      0 var(--space-3);
  --chip-font-size:    var(--text-sm);
  --chip-font-weight:  var(--weight-medium);

  /* --- Tab Bar --- */
  --tab-bg:            transparent;
  --tab-bg-active:     transparent;
  --tab-text:          var(--text-muted);
  --tab-text-active:   var(--text-bright);
  --tab-indicator:     var(--accent-gold);
  --tab-indicator-h:   2px;
  --tab-border:        var(--border-subtle);
  --tab-font-size:     var(--text-sm);
  --tab-font-weight:   var(--weight-semibold);
  --tab-height:        44px;
  --tab-tracking:      var(--tracking-wide);

  /* --- Button (primary) --- */
  --btn-bg:            var(--accent-purple);
  --btn-bg-hover:      #b166f8;
  --btn-text:          #ffffff;
  --btn-radius:        var(--radius-md);
  --btn-height:        36px;
  --btn-padding:       0 var(--space-4);
  --btn-font-size:     var(--text-sm);
  --btn-font-weight:   var(--weight-semibold);

  /* --- Button (ghost) --- */
  --btn-ghost-bg:      transparent;
  --btn-ghost-bg-hover: var(--chip-bg-hover);
  --btn-ghost-border:  var(--border-medium);
  --btn-ghost-text:    var(--text-primary);

  /* --- Input / Select --- */
  --input-bg:          rgba(255, 255, 255, 0.05);
  --input-bg-focus:    rgba(255, 255, 255, 0.08);
  --input-border:      var(--border-subtle);
  --input-border-focus: var(--accent-purple);
  --input-text:        var(--text-primary);
  --input-placeholder: var(--text-muted);
  --input-radius:      var(--radius-md);
  --input-height:      36px;
  --input-padding:     0 var(--space-3);
  --input-font-size:   var(--text-sm);

  /* --- Badge / Rating Pill --- */
  --badge-radius:      var(--radius-sm);
  --badge-font-size:   var(--text-xs);
  --badge-font-weight: var(--weight-bold);
  --badge-padding:     2px 6px;
  --badge-tracking:    var(--tracking-wide);

  /* --- Section Header --- */
  --section-title-size:    var(--text-lg);
  --section-title-weight:  var(--weight-semibold);
  --section-title-color:   var(--text-bright);
  --section-kicker-size:   var(--text-xs);
  --section-kicker-weight: var(--weight-bold);
  --section-kicker-color:  var(--accent-gold);
  --section-kicker-tracking: var(--tracking-widest);

  /* --- Page Layout --- */
  --page-max-width:    1400px;
  --page-gutter:       var(--space-6);       /* horizontal padding on page */
  --sidebar-width:     48px;                 /* desktop rail width */
  --content-gap:       var(--space-6);       /* gap between major sections */
}


/* ============================================================
   BREAKPOINTS (reference — cannot use CSS vars in @media)
   Mobile:  480px
   Tablet:  768px
   Desktop: 1024px
   Wide:    1200px
   ============================================================ */


/* ============================================================
   GLOBAL UTILITY CLASSES
   ============================================================ */

/* Horizontally scrollable table wrapper */
.table-scroll {
  width: 100%;
  overflow-x: auto;
}
.table-scroll table {
  min-width: 1200px;
}

/* Text utilities */
.text-muted    { color: var(--text-muted); }
.text-bright   { color: var(--text-bright); }
.text-gold     { color: var(--accent-gold); }
.text-purple   { color: var(--accent-purple); }

/* Surface utilities */
.surface       { background: var(--bg-surface); }
.surface-raised { background: var(--bg-raised); }

/* Divider — use instead of box-shadows for section separation */
.divider {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 0;
}

/* Screen-reader only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

