1	/* ============================================================
2	   DESIGN TOKENS
3	   Single source of truth for all visual decisions.
4	   Import this file first in any page or component.
5	   ============================================================ */
6	
7	:root {
8	
9	  /* ============================================================
10	     CORE PALETTE
11	     ============================================================ */
12	
13	  /* Backgrounds (darkest to lightest surface) */
14	  --bg-base:       #07060c;   /* page background */
15	  --bg-surface:    #0d0b14;   /* cards, panels */
16	  --bg-raised:     #13111c;   /* elevated elements, dropdowns */
17	  --bg-overlay:    #1a1726;   /* modals, sheets */
18	
19	  /* Backwards-compatible aliases */
20	  --bg-primary:    var(--bg-base);
21	  --bg-secondary:  var(--bg-surface);
22	
23	  /* Text */
24	  --text-bright:   #f4f1ff;
25	  --text-primary:  #e6e6eb;
26	  --text-secondary: rgba(230, 230, 235, 0.70);
27	  --text-muted:    rgba(230, 230, 235, 0.45);
28	  --text-disabled: rgba(230, 230, 235, 0.25);
29	
30	  /* Accents */
31	  --accent-gold:   #facc15;
32	  --accent-gold-dim: rgba(250, 204, 21, 0.15);
33	  --accent-purple: #a855f7;
34	  --accent-purple-dim: rgba(168, 85, 247, 0.15);
35	  --gold:          #d4af37;
36	  --accent-new:    #15b109;
37	
38	  /* Borders (prefer these over box-shadow for separation) */
39	  --border-faint:  rgba(255, 255, 255, 0.05);
40	  --border-subtle: rgba(255, 255, 255, 0.08);
41	  --border-medium: rgba(255, 255, 255, 0.15);
42	  --border-strong: rgba(255, 255, 255, 0.28);
43	
44	
45	  /* ============================================================
46	     RATING TIER COLORS
47	     Canonical source — used by HeroCard and rating badges.
48	     ============================================================ */
49	
50	  --tier-sss-from: #ff4d4d;
51	  --tier-sss-to:   #b91c1c;
52	  --tier-sss-text: #fff5f5;
53	  --tier-sss-glow: rgba(255, 60, 60, 0.55);
54	
55	  --tier-ss-from:  #ffe066;
56	  --tier-ss-to:    #facc15;
57	  --tier-ss-text:  #3a2a00;
58	  --tier-ss-glow:  rgba(255, 224, 102, 0.35);
59	
60	  --tier-s-from:   #fde68a;
61	  --tier-s-to:     #fbbf24;
62	  --tier-s-text:   #3a2a00;
63	  --tier-s-glow:   rgba(251, 191, 36, 0.35);
64	
65	  --tier-a-from:   #fdba74;
66	  --tier-a-to:     #fb923c;
67	  --tier-a-text:   #3b1d00;
68	
69	  --tier-b-from:   #c4b5fd;
70	  --tier-b-to:     #8b5cf6;
71	  --tier-b-text:   #1e103a;
72	
73	  --tier-c-from:   #93c5fd;
74	  --tier-c-to:     #3b82f6;
75	  --tier-c-text:   #001a33;
76	
77	  --tier-d-from:   #5eead4;
78	  --tier-d-to:     #14b8a6;
79	  --tier-d-text:   #002c26;
80	
81	
82	  /* ============================================================
83	     SPACING SCALE (8pt base)
84	     ============================================================ */
85	
86	  --space-1:  4px;
87	  --space-2:  8px;
88	  --space-3:  12px;
89	  --space-4:  16px;
90	  --space-5:  20px;
91	  --space-6:  24px;
92	  --space-8:  32px;
93	  --space-10: 40px;
94	  --space-12: 48px;
95	  --space-16: 64px;
96	  --space-20: 80px;
97	  --space-24: 96px;
98	
99	  /* Backwards-compatible aliases */
100	  --space-xs:  var(--space-1);
101	  --space-sm:  var(--space-2);
102	  --space-md:  var(--space-4);
103	  --space-lg:  var(--space-6);
104	  --space-xl:  var(--space-8);
105	  --space-2xl: var(--space-12);
106	  --space-3xl: var(--space-16);
107	
108	
109	  /* ============================================================
110	     TYPOGRAPHY SCALE
111	     ============================================================ */
112	
113	  /* Font families */
114	  --font-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
115	  --font-mono: "SF Mono", "Fira Code", "Cascadia Code", monospace;
116	
117	  /* Size scale */
118	  --text-xs:   11px;
119	  --text-sm:   13px;
120	  --text-base: 15px;
121	  --text-md:   16px;
122	  --text-lg:   18px;
123	  --text-xl:   20px;
124	  --text-2xl:  24px;
125	  --text-3xl:  30px;
126	  --text-4xl:  38px;
127	
128	  /* Weight */
129	  --weight-normal:    400;
130	  --weight-medium:    500;
131	  --weight-semibold:  600;
132	  --weight-bold:      700;
133	
134	  /* Line height */
135	  --leading-tight:  1.2;
136	  --leading-snug:   1.35;
137	  --leading-normal: 1.5;
138	  --leading-loose:  1.7;
139	
140	  /* Letter spacing */
141	  --tracking-tight:  -0.02em;
142	  --tracking-normal:  0em;
143	  --tracking-wide:    0.04em;
144	  --tracking-widest:  0.10em;
145	
146	
147	  /* ============================================================
148	     BORDER RADIUS SCALE
149	     ============================================================ */
150	
151	  --radius-sm:   4px;
152	  --radius-md:   8px;
153	  --radius-lg:   12px;
154	  --radius-xl:   16px;
155	  --radius-2xl:  20px;
156	  --radius-full: 9999px;
157	
158	
159	  /* ============================================================
160	     ELEVATION (prefer bg tints over shadows for clean look)
161	     Use shadows sparingly — only for floating elements.
162	     ============================================================ */
163	
164	  /* Subtle tint for "elevated" surfaces — no shadow needed */
165	  --surface-tint: rgba(255, 255, 255, 0.03);
166	
167	  /* Shadows: use only for dropdowns, modals, tooltips */
168	  --shadow-sm:  0 1px 3px rgba(0, 0, 0, 0.4);
169	  --shadow-md:  0 4px 12px rgba(0, 0, 0, 0.5);
170	  --shadow-lg:  0 8px 32px rgba(0, 0, 0, 0.6);
171	  --shadow-xl:  0 16px 48px rgba(0, 0, 0, 0.7);
172	
173	
174	  /* ============================================================
175	     Z-INDEX SCALE
176	     ============================================================ */
177	
178	  --z-base:     0;
179	  --z-raised:   10;
180	  --z-dropdown: 100;
181	  --z-overlay:  200;
182	  --z-modal:    300;
183	  --z-toast:    400;
184	  --z-nav:      500;
185	
186	
187	  /* ============================================================
188	     TRANSITIONS
189	     ============================================================ */
190	
191	  --ease-out:   cubic-bezier(0.0, 0.0, 0.2, 1);
192	  --ease-in:    cubic-bezier(0.4, 0.0, 1, 1);
193	  --ease-inout: cubic-bezier(0.4, 0.0, 0.2, 1);
194	
195	  --duration-fast:   120ms;
196	  --duration-normal: 200ms;
197	  --duration-slow:   350ms;
198	
199	  --transition-colors: color var(--duration-normal) var(--ease-out),
200	                       background-color var(--duration-normal) var(--ease-out),
201	                       border-color var(--duration-normal) var(--ease-out);
202	
203	  --transition-transform: transform var(--duration-normal) var(--ease-out);
204	  --transition-opacity:   opacity var(--duration-normal) var(--ease-out);
205	  --transition-all:       all var(--duration-normal) var(--ease-out);
206	
207	
208	  /* ============================================================
209	     COMPONENT TOKENS
210	     These map semantic intent to palette values.
211	     Change here to update all components at once.
212	     ============================================================ */
213	
214	  /* --- Chip / Filter Tag --- */
215	  --chip-bg:           rgba(255, 255, 255, 0.06);
216	  --chip-bg-hover:     rgba(255, 255, 255, 0.10);
217	  --chip-bg-active:    var(--accent-purple-dim);
218	  --chip-border:       var(--border-subtle);
219	  --chip-border-active: var(--accent-purple);
220	  --chip-text:         var(--text-secondary);
221	  --chip-text-active:  var(--accent-purple);
222	  --chip-radius:       var(--radius-full);
223	  --chip-height:       32px;
224	  --chip-padding:      0 var(--space-3);
225	  --chip-font-size:    var(--text-sm);
226	  --chip-font-weight:  var(--weight-medium);
227	
228	  /* --- Tab Bar --- */
229	  --tab-bg:            transparent;
230	  --tab-bg-active:     transparent;
231	  --tab-text:          var(--text-muted);
232	  --tab-text-active:   var(--text-bright);
233	  --tab-indicator:     var(--accent-gold);
234	  --tab-indicator-h:   2px;
235	  --tab-border:        var(--border-subtle);
236	  --tab-font-size:     var(--text-sm);
237	  --tab-font-weight:   var(--weight-semibold);
238	  --tab-height:        44px;
239	  --tab-tracking:      var(--tracking-wide);
240	
241	  /* --- Button (primary) --- */
242	  --btn-bg:            var(--accent-purple);
243	  --btn-bg-hover:      #b166f8;
244	  --btn-text:          #ffffff;
245	  --btn-radius:        var(--radius-md);
246	  --btn-height:        36px;
247	  --btn-padding:       0 var(--space-4);
248	  --btn-font-size:     var(--text-sm);
249	  --btn-font-weight:   var(--weight-semibold);
250	
251	  /* --- Button (ghost) --- */
252	  --btn-ghost-bg:      transparent;
253	  --btn-ghost-bg-hover: var(--chip-bg-hover);
254	  --btn-ghost-border:  var(--border-medium);
255	  --btn-ghost-text:    var(--text-primary);
256	
257	  /* --- Input / Select --- */
258	  --input-bg:          rgba(255, 255, 255, 0.05);
259	  --input-bg-focus:    rgba(255, 255, 255, 0.08);
260	  --input-border:      var(--border-subtle);
261	  --input-border-focus: var(--accent-purple);
262	  --input-text:        var(--text-primary);
263	  --input-placeholder: var(--text-muted);
264	  --input-radius:      var(--radius-md);
265	  --input-height:      36px;
266	  --input-padding:     0 var(--space-3);
267	  --input-font-size:   var(--text-sm);
268	
269	  /* --- Badge / Rating Pill --- */
270	  --badge-radius:      var(--radius-sm);
271	  --badge-font-size:   var(--text-xs);
272	  --badge-font-weight: var(--weight-bold);
273	  --badge-padding:     2px 6px;
274	  --badge-tracking:    var(--tracking-wide);
275	
276	  /* --- Section Header --- */
277	  --section-title-size:    var(--text-lg);
278	  --section-title-weight:  var(--weight-semibold);
279	  --section-title-color:   var(--text-bright);
280	  --section-kicker-size:   var(--text-xs);
281	  --section-kicker-weight: var(--weight-bold);
282	  --section-kicker-color:  var(--accent-gold);
283	  --section-kicker-tracking: var(--tracking-widest);
284	
285	  /* --- Page Layout --- */
286	  --page-max-width:    1400px;
287	  --page-gutter:       var(--space-6);       /* horizontal padding on page */
288	  --sidebar-width:     48px;                 /* desktop rail width */
289	  --content-gap:       var(--space-6);       /* gap between major sections */
290	}
291	
292	
293	/* ============================================================
294	   BREAKPOINTS (reference — cannot use CSS vars in @media)
295	   Mobile:  480px
296	   Tablet:  768px
297	   Desktop: 1024px
298	   Wide:    1200px
299	   ============================================================ */
300	
301	
302	/* ============================================================
303	   GLOBAL UTILITY CLASSES
304	   ============================================================ */
305	
306	/* Horizontally scrollable table wrapper */
307	.table-scroll {
308	  width: 100%;
309	  overflow-x: auto;
310	}
311	.table-scroll table {
312	  min-width: 1200px;
313	}
314	
315	/* Text utilities */
316	.text-muted    { color: var(--text-muted); }
317	.text-bright   { color: var(--text-bright); }
318	.text-gold     { color: var(--accent-gold); }
319	.text-purple   { color: var(--accent-purple); }
320	
321	/* Surface utilities */
322	.surface       { background: var(--bg-surface); }
323	.surface-raised { background: var(--bg-raised); }
324	
325	/* Divider — use instead of box-shadows for section separation */
326	.divider {
327	  border: none;
328	  border-top: 1px solid var(--border-subtle);
329	  margin: 0;
330	}
331	
332	/* Screen-reader only */
333	.sr-only {
334	  position: absolute;
335	  width: 1px;
336	  height: 1px;
337	  padding: 0;
338	  margin: -1px;
339	  overflow: hidden;
340	  clip: rect(0, 0, 0, 0);
341	  white-space: nowrap;
342	  border: 0;
343	}
