file.content:
---
import Sidebar from '../components/Sidebar.astro';
import Footer from '../components/Footer.astro';
import Analytics from '@vercel/analytics/astro';

interface Props {
  title?: string;
  description?: string;
  image?: string;
}

const {
  title = "Motto Immortal Database",
  description = "The complete hero database for Motto Immortal. Stats, skills, tier lists, team comps and boss guides for all heroes.",
  image = "/og-default.png"
} = Astro.props;

const canonicalURL = new URL(Astro.url.pathname, Astro.site);
---

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta name="description" content={description} />
  <meta name="google-site-verification" content="t6k7HFdRY9c1Q_Rb80K63Aguqwr8zctSXQ28Oa2W9s4" />
  <link rel="canonical" href={canonicalURL} />

  <!-- Open Graph -->
  <meta property="og:type" content="website" />
  <meta property="og:url" content={canonicalURL} />
  <meta property="og:title" content={title} />
  <meta property="og:description" content={description} />
  <meta property="og:image" content={new URL(image, Astro.site)} />

  <!-- Twitter Card -->
  <meta name="twitter:card" content="summary_large_image" />
  <meta name="twitter:title" content={title} />
  <meta name="twitter:description" content={description} />
  <meta name="twitter:image" content={new URL(image, Astro.site)} />

  <title>{title}</title>
  <!-- Google AdSense -->
  <script is:inline async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-1272647850363446" crossorigin="anonymous"></script>
  <Analytics />
  <slot name="head" />
  <script is:inline>
    (function() {
      var lang = localStorage.getItem('lang') || 'en';
      document.documentElement.setAttribute('data-lang', lang);
    })();
  </script>
  <script is:inline src="/i18n.js"></script>
</head>
<body>
  <Sidebar />
  <slot />
  <Footer />
</body>
</html>

<style is:global>
  @import '../styles/tokens.css';
  @import '../styles/components.css';

  *, *::before, *::after {
    box-sizing: border-box;
  }

  @import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap");

  html, body {
    margin: 0;
    padding: 0;
    font-family: "Inter", system-ui, sans-serif;
    background:
      radial-gradient(ellipse at 30% -10%, rgba(120, 90, 200, 0.07), transparent 60%),
      radial-gradient(ellipse at 80% 20%, rgba(255, 215, 100, 0.04), transparent 55%),
      linear-gradient(to bottom, #0d0b10, #07060c);
    background-attachment: fixed;
    color: var(--text-primary);
    min-height: 100vh;
  }

  /* Offset for desktop sidebar rail */
  body {
    margin-left: var(--sidebar-width); /* 48px */
  }

  @media (max-width: 768px) {
    body {
      margin-left: 0;
      margin-bottom: 56px; /* mobile bottom nav */
    }
  }
</style>

