/* ============================================================
   BASE STYLES
   Global typography, body, and layout primitives.
   Consumes tokens from tokens.css.
   Import order: tokens -> reset -> base -> components
   ============================================================ */

/* ============================================================
   BODY & HTML
   ============================================================ */

html,
body {
  font-family: "Inter", var(--font-base);
  background:
    radial-gradient(ellipse at 30% -10%, rgba(120, 90, 200, 0.07), transparent 60%),
    radial-gradient(ellipse at 80% 20%, rgba(255, 215, 100, 0.04), transparent 55%),
    linear-gradient(to bottom, #0d0b10, var(--bg-base));
  background-attachment: fixed;
  background-color: var(--bg-base);
  color: var(--text-primary);
  font-size: var(--text-base);
  min-height: 100vh;
}

/* Desktop sidebar rail offset */
body {
  margin-left: var(--sidebar-width);
}

@media (max-width: 768px) {
  body {
    margin-left: 0;
    margin-bottom: 56px; /* mobile bottom nav */
  }
}


/* ============================================================
   TYPOGRAPHY
   ============================================================ */

h1, h2, h3, h4, h5, h6 {
  font-weight: var(--weight-bold);
  line-height: var(--leading-tight);
  color: var(--text-bright);
}

p {
  line-height: var(--leading-normal);
  color: var(--text-primary);
}

small {
  font-size: var(--text-sm);
  color: var(--text-muted);
}

strong {
  font-weight: var(--weight-semibold);
}

code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  background: var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 1px 5px;
}


/* ============================================================
   LINKS
   ============================================================ */

a:hover {
  color: var(--accent-gold);
}


/* ============================================================
   FOCUS VISIBLE
   Keyboard-only focus ring, consistent across all interactive elements.
   ============================================================ */

:focus-visible {
  outline: 2px solid var(--accent-purple);
  outline-offset: 2px;
}

/* Remove default focus ring (replaced by :focus-visible) */
:focus:not(:focus-visible) {
  outline: none;
}


/* ============================================================
   SCROLLBAR
   ============================================================ */

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.22);
}


/* ============================================================
   SELECTION
   ============================================================ */

::selection {
  background: rgba(168, 85, 247, 0.35);
  color: var(--text-bright);
}


/* ============================================================
   PAGE WRAPPER (global layout primitive)
   Consistent max-width + horizontal padding on all pages.
   Usage: <div class="page-wrapper"> ... </div>
   ============================================================ */

.page-wrapper {
  max-width: var(--page-max-width);
  margin: 0 auto;
  padding: 0 var(--page-gutter);
  width: 100%;
}

@media (max-width: 768px) {
  .page-wrapper {
    padding: 0 var(--space-4);
  }
}

@media (max-width: 480px) {
  .page-wrapper {
    padding: 0 var(--space-3);
  }
}


/* ============================================================
   DIVIDER UTILITY
   ============================================================ */

.divider {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 0;
}


/* ============================================================
   SCREEN-READER ONLY
   ============================================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

