.donate-btn-kofi {
  border-color: rgba(255, 94, 91, 0.6);
  color: #ff5e5b;
  width: 100%;
  justify-content: center;
}

.donate-btn-kofi:hover {
  background: rgba(255, 94, 91, 0.1);
  border-color: rgba(255, 94, 91, 0.9);
  box-shadow: 0 4px 16px rgba(255, 94, 91, 0.2);
  color: #ff7875;
