.donate-btn-paypal {
  width: 100%;
  justify-content: center;
}

.ad-slot-list,
.ad-slot-hero {
  width: 100%;
  max-width: 900px;
  margin: 0 auto var(--space-6);
  min-height: 90px;
  text-align: center;
}

.ad-slot-hero {
  margin-top: var(--space-8);
  padding: 0 var(--space-4);
}

.support-alt {
  font-size: var(--text-xs);
  color: var(--text-disabled);
  text-align: center;
  margin: 0;
  max-width: 200px;
  line-height: var(--leading-normal);
}

@media (max-width: 768px) {
  .support-card {
    flex-direction: column;
    gap: var(--space-8);
    padding: var(--space-6);
  }

  .support-cta {
    width: 100%;
    align-items: flex-start;
  }

