  font-family: inherit;
  letter-spacing: var(--tab-tracking);
  text-transform: uppercase;
  cursor: pointer;
  transition: var(--transition-colors);
  white-space: nowrap;
}

.tab:hover {
  color: var(--text-primary);
}

.tab.is-active {
  color: var(--tab-text-active);
  border-bottom-color: var(--tab-indicator);
}

/* SUPPORT SECTION */
.support-section {
  margin-top: 80px;
  margin-left: auto;
  margin-right: auto;
}

.support-card {
  display: flex;
  gap: 48px;
  align-items: center;
  background: rgba(255, 255, 255, 0.025);
