  flex-shrink: 0;
  color: var(--accent-gold);
}

.support-desc {
  font-size: 0.95rem;
  color: var(--text-secondary);
  line-height: 1.65;
  margin: 0 0 20px;
}

.support-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.support-list li {
  font-size: 0.9rem;
  color: rgba(230, 230, 235, 0.6);
  padding-left: 18px;
  position: relative;
}

.support-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
