  border-color: rgba(255, 94, 91, 0.6);
  color: #ff5e5b;
  width: 100%;
  justify-content: center;
}

.donate-btn-kofi:hover {
  background: rgba(255, 94, 91, 0.1);
  border-color: rgba(255, 94, 91, 0.9);
  box-shadow: 0 4px 16px rgba(255, 94, 91, 0.2);
  color: #ff7875;
}

.donate-btn-paypal {
  width: 100%;
  justify-content: center;
}

/* ─── Ad Slots ─── */
.ad-slot-list,
.ad-slot-hero {
  width: 100%;
  max-width: 900px;
  margin: 0 auto 24px;
  min-height: 90px;
  text-align: center;
}

.ad-slot-hero {
  margin-top: 32px;
  padding: 0 16px;
}

.support-alt {
  font-size: 0.8rem;
  color: rgba(230, 230, 235, 0.4);
  text-align: center;
