@media (max-width: 768px) {
  .support-card {
    flex-direction: column;
    gap: 32px;
    padding: 28px;
  }

  .support-cta {
    width: 100%;
    align-items: flex-start;
  }

  .support-alt {
    max-width: none;
    text-align: left;
  }
}

@media (max-width: 480px) {
  .support-card {
    padding: 20px;
  }

  .support-headline {
    font-size: 1.4rem;
  }
}

