630	<script>
631	document.addEventListener("DOMContentLoaded", () => {
632	  const searchInput = document.getElementById("searchInput") as HTMLInputElement;
633	  const resetButton = document.getElementById("resetFilters");
634	  const heroCounter = document.getElementById("heroCounter");
635	  const heroGrid = document.getElementById("heroGrid") as HTMLElement;
636	  const heroList = document.getElementById("heroList") as HTMLElement;
637	  const heroListBody = document.getElementById("heroListBody") as HTMLElement;
638	  const sortSelect = document.getElementById("sortSelect") as HTMLSelectElement;
639	  const viewGridBtn = document.getElementById("viewGrid") as HTMLButtonElement;
640	  const viewListBtn = document.getElementById("viewList") as HTMLButtonElement;
641	
642	  const roleChips = document.querySelectorAll(".role-chip");
643	  const factionChips = document.querySelectorAll(".faction-chip");
644	  const heroCards = document.querySelectorAll<HTMLElement>(".hero-wrapper");
645	  const listRows = document.querySelectorAll<HTMLElement>(".hero-row");
646	  const classChips = document.querySelectorAll(".class-chip");
647	  const rarityChips = document.querySelectorAll(".rarity-chip");
648	  const tagChips = document.querySelectorAll(".tag-chip");
649	
650	  const RATING_ORDER: Record<string, number> = { sss: 7, ss: 6, s: 5, a: 4, b: 3, c: 2, d: 1, "n/a": 0 };
651	  const RARITY_ORDER: Record<string, number> = { legendary: 3, epic: 2, common: 1 };
652	
653	  let activeTag: string | null = null;
654	  let activeRoles = new Set<string>();
655	  let activeClasses = new Set<string>();
656	  let activeRarities = new Set<string>();
657	  let activeFactions = new Set<string>();
658	
659	  // ---- View toggle ----
660	
661	  let currentView: "grid" | "list" = (localStorage.getItem("heroView") as "grid" | "list") || "grid";
662	
663	  function setView(v: "grid" | "list") {
664	    currentView = v;
665	    localStorage.setItem("heroView", v);
666	    if (v === "grid") {
667	      heroGrid.style.display = "";
668	      heroList.style.display = "none";
669	      viewGridBtn.classList.add("active");
670	      viewListBtn.classList.remove("active");
671	    } else {
672	      heroGrid.style.display = "none";
673	      heroList.style.display = "";
674	      viewGridBtn.classList.remove("active");
675	      viewListBtn.classList.add("active");
676	    }
677	  }
678	
679	  viewGridBtn.addEventListener("click", () => setView("grid"));
680	  viewListBtn.addEventListener("click", () => setView("list"));
681	
682	  // apply persisted view on load
683	  setView(currentView);
684	
685	  // ---- Filtering ----
686	
687	  function matchesFilters(el: HTMLElement): boolean {
688	    const query = (searchInput.value || "").toLowerCase();
689	    const name = el.dataset.name || "";
690	    const cls = el.dataset.class || "";
691	    const role = el.dataset.role || "";
692	    const rarity = el.dataset.rarity || "";
693	    const faction = el.dataset.faction || "";
694	    const tags = el.dataset.tags || "";
695	
696	    return (
697	      (!activeTag || tags.includes(activeTag)) &&
698	      (!query || name.includes(query) || cls.includes(query) || role.includes(query) || faction.includes(query) || rarity.includes(query)) &&
699	      (activeClasses.size === 0 || activeClasses.has(cls)) &&
700	      (activeRoles.size === 0 || activeRoles.has(role)) &&
701	      (activeRarities.size === 0 || activeRarities.has(rarity)) &&
702	      (activeFactions.size === 0 || activeFactions.has(faction))
703	    );
704	  }
705	
706	  function applyFilters() {
707	    let visible = 0;
708	    heroCards.forEach(card => {
709	      const show = matchesFilters(card);
710	      card.style.display = show ? "block" : "none";
711	      if (show) visible++;
712	    });
713	    listRows.forEach(row => {
714	      row.style.display = matchesFilters(row) ? "" : "none";
715	    });
716	    const lang = localStorage.getItem('lang') || 'en';
717	    const suffix = lang === 'ru' ? ' Героев показано' : ' Heroes shown';
718	    heroCounter!.textContent = `${visible}${suffix}`;
719	  }
720	
721	  // ---- Sorting ----
722	
723	  const TIER_ORDER: Record<string, number> = { "T0": 1, "T0.5": 2, "T1": 3, "T2": 4, "T10": 5, "": 9 };
724	
725	  const ratingVal  = (el: HTMLElement) => RATING_ORDER[el.dataset.rating || ""] ?? 0;
726	  const rarityVal  = (el: HTMLElement) => RARITY_ORDER[el.dataset.rarity || ""] ?? 0;
727	  const nameVal    = (el: HTMLElement) => el.dataset.name || "";
728	
729	  function dropdownCompareFn(a: HTMLElement, b: HTMLElement): number {
730	    const value = sortSelect.value;
731	    switch (value) {
732	      case "name-asc":    return nameVal(a).localeCompare(nameVal(b));
733	      case "name-desc":   return nameVal(b).localeCompare(nameVal(a));
734	      case "rating-desc": { const d = ratingVal(b) - ratingVal(a); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
735	      case "rating-asc":  { const d = ratingVal(a) - ratingVal(b); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
736	      case "class":       return (a.dataset.class || "").localeCompare(b.dataset.class || "");
737	      case "rarity-desc": { const d = rarityVal(b) - rarityVal(a); return d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)); }
738	      default: return 0;
739	    }
740	  }
741	
742	  function sortHeroes() {
743	    // sort grid cards by dropdown
744	    Array.from(heroGrid.querySelectorAll<HTMLElement>(".hero-wrapper"))
745	      .sort(dropdownCompareFn)
746	      .forEach(el => heroGrid.appendChild(el));
747	    // sort list rows by dropdown (resets column sort)
748	    Array.from(heroListBody.querySelectorAll<HTMLElement>(".hero-row"))
749	      .sort(dropdownCompareFn)
750	      .forEach(el => heroListBody.appendChild(el));
751	    // clear column sort state
752	    listSortCol = null;
753	    listSortDir = "asc";
754	    updateColHeaders();
755	  }
756	
757	  sortSelect.addEventListener("change", () => { sortHeroes(); applyFilters(); });
758	
759	  // ---- Column header sorting (list view only) ----
760	
761	  let listSortCol: string | null = null;
762	  let listSortDir: "asc" | "desc" = "asc";
763	
764	  function updateColHeaders() {
765	    document.querySelectorAll<HTMLElement>(".col-sortable").forEach(th => {
766	      th.classList.remove("sort-asc", "sort-desc");
767	      if (th.dataset.col === listSortCol) {
768	        th.classList.add(listSortDir === "asc" ? "sort-asc" : "sort-desc");
769	      }
770	    });
771	  }
772	
773	  function sortListByCol(col: string) {
774	    if (listSortCol === col) {
775	      listSortDir = listSortDir === "asc" ? "desc" : "asc";
776	    } else {
777	      listSortCol = col;
778	      listSortDir = col === "overall" || col === "pvp" || col === "pve" ? "desc" : "asc";
779	    }
780	
781	    const dir = listSortDir === "asc" ? 1 : -1;
782	
783	    Array.from(heroListBody.querySelectorAll<HTMLElement>(".hero-row"))
784	      .sort((a, b) => {
785	        switch (col) {
786	          case "name":
787	            return dir * nameVal(a).localeCompare(nameVal(b));
788	          case "overall": {
789	            const d = (RATING_ORDER[a.dataset.rating || ""] ?? 0) - (RATING_ORDER[b.dataset.rating || ""] ?? 0);
790	            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
791	          }
792	          case "pvp": {
793	            const d = (RATING_ORDER[a.dataset.pvp || ""] ?? 0) - (RATING_ORDER[b.dataset.pvp || ""] ?? 0);
794	            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
795	          }
796	          case "pve": {
797	            const d = (RATING_ORDER[a.dataset.pve || ""] ?? 0) - (RATING_ORDER[b.dataset.pve || ""] ?? 0);
798	            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
799	          }
800	          case "tier": {
801	            const ta = TIER_ORDER[a.dataset.excelTier || ""] ?? 9;
802	            const tb = TIER_ORDER[b.dataset.excelTier || ""] ?? 9;
803	            const d = ta - tb;
804	            return dir * (d !== 0 ? d : nameVal(a).localeCompare(nameVal(b)));
805	          }
806	          default: return 0;
807	        }
808	      })
809	      .forEach(el => heroListBody.appendChild(el));
810	
811	    updateColHeaders();
812	    applyFilters();
813	  }
814	
815	  document.querySelectorAll<HTMLElement>(".col-sortable").forEach(th => {
816	    th.addEventListener("click", () => sortListByCol(th.dataset.col || ""));
817	  });
818	
819	  // ---- Chip filters ----
820	
821	  searchInput.addEventListener("input", applyFilters);
822	
