}
.mechanic-title {
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--faction-a);
}
.mechanic-summary {
  margin: 0;
  font-size: 0.87rem;
  line-height: 1.6;
  color: rgba(255,255,255,0.78);
}
.depth-badge {
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.depth-high { background: rgba(168,85,247,0.15); border: 1px solid rgba(168,85,247,0.35); color: #d8b4fe; }
.depth-mid  { background: rgba(59,130,246,0.15); border: 1px solid rgba(59,130,246,0.35); color: #93c5fd; }
.depth-low  { background: rgba(107,114,128,0.15); border: 1px solid rgba(107,114,128,0.35); color: #d1d5db; }
.misunderstood-badge {
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(234,179,8,0.12);
  border: 1px solid rgba(234,179,8,0.35);
  color: #fde68a;
}

/* Key Stats Grid */
.key-stats-label {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}
.key-stats-sub { font-size: 0.65rem; font-weight: 500; text-transform: none; letter-spacing: 0; color: rgba(255,255,255,0.3); }

.key-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.key-stat-block {
  background: rgba(0,0,0,0.22);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  padding: 14px 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: border-color 0.2s;
}
.key-stat-block:hover { border-color: rgba(255,255,255,0.14); }

.key-stat-value {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-bright, #fff);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.key-stat-label {
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255,255,255,0.45);
}
.key-stat-bar {
  margin-top: 6px;
  height: 3px;
  background: rgba(255,255,255,0.08);
  border-radius: 2px;
  overflow: hidden;
}
.key-stat-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--faction-a), var(--faction-b));
  border-radius: 2px;
  transition: width 0.4s ease;
}

/* =============================================
   SECTION 2: SKILLS
   ============================================= */
.skill-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 0;
  overflow-x: auto;
  padding-bottom: 0;
  scrollbar-width: none;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.skill-tabs::-webkit-scrollbar { display: none; }

.skill-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 16px 14px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  color: rgba(255,255,255,0.5);
  transition: all 0.2s ease;
  white-space: nowrap;
  min-width: 80px;
  position: relative;
  bottom: -1px;
}
.skill-tab:hover { color: rgba(255,255,255,0.8); }
.skill-tab.active {
  color: #fff;
  border-bottom-color: var(--faction-a);
}
.skill-tab.is-ultimate.active { border-bottom-color: #fbbf24; }
.skill-tab.is-relic.active { border-bottom-color: #a78bfa; }

.skill-tab-icon {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background-size: cover;
  background-position: center;
  border: 2px solid rgba(255,255,255,0.12);
  transition: border-color 0.2s;
}
.skill-tab.active .skill-tab-icon { border-color: var(--faction-a); box-shadow: 0 0 12px var(--faction-glow); }
.skill-tab.is-ultimate.active .skill-tab-icon { border-color: #fbbf24; box-shadow: 0 0 14px rgba(251,191,36,0.4); }
.skill-tab.is-relic.active .skill-tab-icon { border-color: #a78bfa; box-shadow: 0 0 12px rgba(167,139,250,0.4); }

.skill-tab-label {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.dmg-type-chip {
  font-size: 0.58rem;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.dmg-type-chip.dmg-magical  { background: rgba(59,130,246,0.2); color: #93c5fd; border: 1px solid rgba(59,130,246,0.3); }
.dmg-type-chip.dmg-physical { background: rgba(249,115,22,0.2); color: #fdba74; border: 1px solid rgba(249,115,22,0.3); }
.dmg-type-chip.dmg-true     { background: rgba(255,255,255,0.1); color: #e5e7eb; border: 1px solid rgba(255,255,255,0.2); }

/* Skill Panels */
.skill-panels { margin-top: 0; }

.skill-panel { display: none; }
.skill-panel.active { display: block; }

.skill-panel-inner {
  padding: 28px;
  background: rgba(0,0,0,0.22);
  border: 1px solid rgba(255,255,255,0.08);
  border-top: none;
  border-radius: 0 0 14px 14px;
}
