.virtue-set-column {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.virtue-set-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.virtue-set-title {
  font-size: 1rem;
  font-weight: 700;
  color: rgba(255,255,255,0.9);
  letter-spacing: 0.02em;
}
.virtue-set-count {
  font-size: 0.72rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.5);
  letter-spacing: 0.03em;
}
.virtue-pieces {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.virtue-card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.virtue-card-media-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 4px;
}
.virtue-card-media {
  width: 72px;
  height: 92px;
  object-fit: contain;
  filter: drop-shadow(0 10px 18px rgba(0,0,0,0.28));
}
.virtue-card-media--missing {
  border: 1px dashed rgba(255,255,255,0.12);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));
  display: flex;
  align-items: center;
  justify-content: center;
}
.virtue-card-media--missing span {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.28);
}
.virtue-header {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.virtue-name {
  font-size: 0.9rem;
  font-weight: 700;
}
.virtue-rarity-blue  { border-color: rgba(96,165,250,0.25); }
.virtue-rarity-purple { border-color: rgba(167,139,250,0.35); }
.virtue-rarity-gold  { border-color: rgba(234,179,8,0.35); }
.virtue-rarity-red   { border-color: rgba(239,68,68,0.45); }
.virtue-rarity-blue  .virtue-name { color: #60a5fa; }
.virtue-rarity-purple .virtue-name { color: #a78bfa; }
.virtue-rarity-gold  .virtue-name { color: #eab308; }
.virtue-rarity-red   .virtue-name { color: #ef4444; }

