.virtue-singular-badge {
  font-size: 0.68rem;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 20px;
  background: rgba(255,255,255,0.05);
  color: rgba(255,255,255,0.35);
  letter-spacing: 0.03em;
}
.virtue-bp {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.4);
}
.virtue-stats-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.virtue-stat {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,0.75);
}
.virtue-bonuses {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding-top: 10px;
  margin-top: 2px;
}
.virtue-bonus-row {
  display: flex;
  gap: 8px;
  align-items: flex-start;
}
.virtue-bonus-label {
  flex-shrink: 0;
  font-size: 0.68rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 6px;
  background: rgba(255,255,255,0.1);
  color: var(--faction-a);
  letter-spacing: 0.04em;
  margin-top: 2px;
}
.virtue-bonus-text {
  font-size: 0.8rem;
  line-height: 1.5;
  color: rgba(255,255,255,0.6);
}
.virtue-comment {
  font-size: 0.82rem;
  line-height: 1.5;
  color: rgba(255,255,255,0.5);
  font-style: italic;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding-top: 8px;
}

/* =============================================
   SECTION 9: VIDEOS
   ============================================= */
.video-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(480px, 1fr));
  gap: 28px;
}
.video-card { display: flex; flex-direction: column; gap: 10px; }
.video-wrapper {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  background: rgba(0,0,0,0.3);
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.08);
}
.video-wrapper iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: none;
}
.video-info { padding: 4px 0; }
.video-title { font-size: 0.9rem; font-weight: 700; color: #fff; margin: 0 0 3px; line-height: 1.35; }
.video-author { font-size: 0.8rem; color: rgba(255,255,255,0.5); margin: 0; }

/* =============================================
   RESPONSIVE
   ============================================= */
@media (max-width: 1024px) {
  .stat-columns { grid-template-columns: 1fr 1fr; }
  .investment-grid { grid-template-columns: 1fr; }
}

@media (max-width: 900px) {
  .profile-grid { grid-template-columns: 1fr; gap: 24px; }
  .big-rating-tiles { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .page-hero-name { display: none; }
  .showcase { height: 65vh; min-height: 380px; }
  .showcase-name { font-size: clamp(2rem, 8vw, 3rem); }
  .showcase-identity { padding: 0 20px 28px; }
  .key-stats-grid { grid-template-columns: repeat(2, 1fr); }
  .big-rating-tiles { grid-template-columns: repeat(3,1fr); gap: 8px; }
  .big-rating-val { font-size: 2rem; }
  .stat-columns { grid-template-columns: 1fr; gap: 16px; }
  .scroll-content { padding: 0 16px 80px; }
  .syn-links-grid { grid-template-columns: 1fr; }
  .video-grid { grid-template-columns: 1fr; }
  .skill-panel-inner { padding: 16px; }
  .skill-body--has-video { grid-template-columns: 1fr; }
  .showcase-nav { width: 38px; height: 38px; }
  .showcase-nav.prev { left: 12px; }
  .showcase-nav.next { right: 12px; }
}

@media (max-width: 480px) {
  .big-rating-tiles { grid-template-columns: 1fr; max-width: 300px; margin-left: auto; margin-right: auto; }
  .key-stats-grid { grid-template-columns: repeat(2, 1fr); }
  .skill-tab { min-width: 70px; padding: 8px 10px 12px; }
  .skill-tab-icon { width: 36px; height: 36px; }
}
</style>

<script>
  // ── Skill tab switching ──
  const skillTabs = document.querySelectorAll('.skill-tab');
  const skillPanels = document.querySelectorAll('.skill-panel');

  function loadPanelVideo(panel: Element | null) {
    if (!panel) return;
    const video = panel.querySelector<HTMLVideoElement>('.skill-video');
    if (!video) return;
    const src = video.getAttribute('data-video-src');
    if (src && !video.src) {
      video.src = src;
      video.load();
      video.play().catch(() => {});
    } else if (video.src && video.paused) {
      video.play().catch(() => {});
    }
  }

  skillTabs.forEach(tab => {
    tab.addEventListener('click', () => {
      const idx = tab.getAttribute('data-skill-tab');
      skillTabs.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-selected','false'); });
      skillPanels.forEach(p => p.classList.remove('active'));
      tab.classList.add('active');
      tab.setAttribute('aria-selected','true');
      const panel = document.querySelector(`.skill-panel[data-skill-panel="${idx}"]`);
      if (panel) panel.classList.add('active');
      loadPanelVideo(panel);
    });
  });

  // Load video for initially active panel (skill 1)
  loadPanelVideo(document.querySelector('.skill-panel.active'));

  // Arrow key cycling through skill tabs
  document.addEventListener('keydown', (e) => {
    const active = document.querySelector('.skill-tab.active');
    if (!active) return;
    const tabs = Array.from(skillTabs) as HTMLElement[];
    const i = tabs.indexOf(active as HTMLElement);
    if (e.key === 'ArrowRight' && i < tabs.length - 1) tabs[i+1].click();
    if (e.key === 'ArrowLeft'  && i > 0)               tabs[i-1].click();
  });

  // ── Composition mode tabs ──
  const compTabs = document.querySelectorAll('.comp-mode-tab');
  const compPanels = document.querySelectorAll('.comp-panel');

  function setCompMode(mode: string) {
    compTabs.forEach(t => t.classList.toggle('active', t.getAttribute('data-comp-mode') === mode));
    compPanels.forEach(p => {
      const isMatch = p.getAttribute('data-comp-panel') === mode;
      (p as HTMLElement).style.display = isMatch ? 'block' : 'none';
      p.classList.toggle('active', isMatch);
    });
    try { localStorage.setItem('heroCompMode', mode); } catch {}
  }

  // Restore from localStorage
  let initMode = 'general';
  try {
    const saved = localStorage.getItem('heroCompMode');
    if (saved && ['general','pve','pvp'].includes(saved)) initMode = saved;
  } catch {}
  setCompMode(initMode);

  compTabs.forEach(tab => {
    tab.addEventListener('click', () => setCompMode(tab.getAttribute('data-comp-mode') ?? 'general'));
  });

  // ── Dot nav: IntersectionObserver ──
  const dotItems = document.querySelectorAll('.dot-nav-item');
  const sections = document.querySelectorAll('.content-section[id]');

  if (dotItems.length > 0 && sections.length > 0) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const id = entry.target.getAttribute('id');
          dotItems.forEach(d => d.classList.toggle('active', d.getAttribute('data-section') === id));
        }
      });
    }, { rootMargin: '-40% 0px -50% 0px', threshold: 0 });

    sections.forEach(s => observer.observe(s));
  }

  // Smooth scroll for dot nav
  dotItems.forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();
      const targetId = item.getAttribute('data-section') ?? '';
      const target = document.getElementById(targetId);
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });
</script>
<script>
  function initVideos(container: Element | Document = document) {
    container.querySelectorAll<HTMLVideoElement>('video[data-video-src]').forEach(video => {
      if (!video.src) {
        video.src = video.dataset.videoSrc!;
        video.load();
      }
    });
  }

  // Init videos in the initially active panel
  initVideos();

  // When switching tabs, init + play video in the newly active panel
  document.querySelectorAll('[data-skill-tab]').forEach(tab => {
    tab.addEventListener('click', () => {
      const panel = document.querySelector('.skill-panel.active');
      if (panel) {
        initVideos(panel);
        panel.querySelectorAll<HTMLVideoElement>('video').forEach(v => v.play());
      }
    });
  });
</script>

