/* =============================================
   CINEMATIC SHOWCASE
   ============================================= */
.showcase {
  position: relative;
  width: 100%;
  height: 88vh;
  min-height: 520px;
  max-height: 900px;
  overflow: hidden;
}

.showcase-bg {
  position: absolute;
  inset: 0;
  background-image: url(https://pub-a33abfbc3135413881a1d8eb86543559.r2.dev/hall.webp);
  background-size: cover;
  background-position: center top;
  background-repeat: no-repeat;
}

.showcase-art {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center var(--hero-img-y, 14%);
  background-repeat: no-repeat;
  transform: scale(1.04);
  transition: transform 8s ease-out;
}
.showcase:hover .showcase-art { transform: scale(1); }


.showcase-overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to bottom, rgba(7,6,12,0.25) 0%, transparent 30%, transparent 50%, rgba(7,6,12,0.92) 85%, rgba(7,6,12,1) 100%),
    linear-gradient(to right, rgba(7,6,12,0.35) 0%, transparent 40%);
}

/* Prev / Next arrows */
.showcase-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(7,6,12,0.55);
  border: 1px solid rgba(255,255,255,0.15);
  backdrop-filter: blur(10px);
  color: rgba(255,255,255,0.8);
  text-decoration: none;
  transition: all 0.2s ease;
  pointer-events: auto;
}
.showcase-nav svg { width: 20px; height: 20px; }
.showcase-nav.prev { left: 20px; }
.showcase-nav.next { right: 20px; }
.showcase-nav:hover { background: rgba(30,30,40,0.85); border-color: var(--faction-a); color: var(--faction-a); transform: translateY(-50%) scale(1.08); }
.showcase-nav.disabled { opacity: 0.2; pointer-events: none; }

/* Identity block at bottom of showcase */
.showcase-identity {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10;
  padding: 0 40px 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.showcase-name {
  font-size: clamp(2.8rem, 6vw, 5.5rem);
  font-weight: 800;
  line-height: 1.0;
  color: #fff;
  margin: 0 0 14px;
  text-shadow: 0 4px 32px rgba(0,0,0,0.6);
  letter-spacing: -0.02em;
}

.showcase-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.id-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 12px;
  background: rgba(0,0,0,0.45);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
  color: #fff;
  backdrop-filter: blur(8px);
}
.id-badge-icon {
  width: 16px;
  height: 16px;
  object-fit: contain;
}
.rarity-badge {
  border-color: var(--faction-a);
  color: var(--faction-a);
}

.showcase-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.showcase-tag {
  padding: 3px 10px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 600;
  color: rgba(255,255,255,0.65);
  backdrop-filter: blur(6px);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.showcase-scroll-hint {
  position: absolute;
  bottom: 16px;
  right: 40px;
  z-index: 10;
  animation: bounce 2s ease-in-out infinite;
  color: rgba(255,255,255,0.35);
}
.showcase-scroll-hint svg { width: 20px; height: 20px; }
@keyframes bounce {
  0%,100% { transform: translateY(0); }
  50% { transform: translateY(6px); }
}

